solutionPython:
import sys
from collections import deque, Counter


def islands(inp):
    lines = inp.split("\n")
    r, c = map(int, lines[0].split())
    g = [list(lines[i + 1].strip()) for i in range(r)]
    cnt = 0
    for i in range(r):
        for j in range(c):
            if g[i][j] == "1":
                cnt += 1
                g[i][j] = "0"
                q = deque([(i, j)])
                while q:
                    x, y = q.popleft()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < r and 0 <= ny < c and g[nx][ny] == "1":
                            g[nx][ny] = "0"
                            q.append((nx, ny))
    return str(cnt)


print(islands(sys.stdin.read().rstrip("\n")))

