import sys


def coin_change(inp):
    lines = inp.split("\n")
    n, amt = map(int, lines[0].split())
    coins = list(map(int, lines[1].split()))
    INF = 10**9
    dp = [0] + [INF] * amt
    for x in range(1, amt + 1):
        for c in coins:
            if c <= x and dp[x - c] + 1 < dp[x]:
                dp[x] = dp[x - c] + 1
    return str(dp[amt] if dp[amt] < INF else -1)


print(coin_change(sys.stdin.read().rstrip("\n")))

