import sys
from bisect import bisect_left


def lis(inp):
    a = list(map(int, inp.split("\n")[1].split()))
    tails = []
    for x in a:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return str(len(tails))


print(lis(sys.stdin.read().rstrip("\n")))

