import sys
import heapq


def arr(a):
    return " ".join(map(str, a))


def dijkstra(inp):
    lines = inp.split("\n")
    n, m, s = map(int, lines[0].split())
    g = [[] for _ in range(n)]
    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        g[u].append((v, w)); g[v].append((u, w))
    INF = float("inf")
    d = [INF] * n
    d[s] = 0
    pq = [(0, s)]
    while pq:
        du, u = heapq.heappop(pq)
        if du > d[u]:
            continue
        for v, w in g[u]:
            if du + w < d[v]:
                d[v] = du + w
                heapq.heappush(pq, (d[v], v))
    return arr([x if x < INF else -1 for x in d])


print(dijkstra(sys.stdin.read().rstrip("\n")))

