def nqueens(inp):
    n = int(inp)
    full = (1 << n) - 1

    def go(cols, d1, d2):
        if cols == full:
            return 1
        cnt, avail = 0, full & ~(cols | d1 | d2)
        while avail:
            bit = avail & -avail
            avail -= bit
            cnt += go(cols | bit, ((d1 | bit) << 1) & full, (d2 | bit) >> 1)
        return cnt
    return str(go(0, 0, 0))


