import sys
from collections import deque, Counter


def level_order(inp):
    toks = inp.split("\n")[1].split()
    root = {"v": toks[0], "l": None, "r": None}
    q, i = deque([root]), 1
    while q and i < len(toks):
        node = q.popleft()
        for side in ("l", "r"):
            if i < len(toks):
                if toks[i] != "null":
                    node[side] = {"v": toks[i], "l": None, "r": None}
                    q.append(node[side])
                i += 1
    out, q = [], deque([root])
    while q:
        level = []
        for _ in range(len(q)):
            nd = q.popleft(); level.append(nd["v"])
            for side in ("l", "r"):
                if nd[side]:
                    q.append(nd[side])
        out.append(" ".join(level))
    return "\n".join(out)


print(level_order(sys.stdin.read().rstrip("\n")))

