import sys


def mst(inp):
    lines = inp.split("\n")
    n, m = map(int, lines[0].split())
    edges = sorted((tuple(map(int, lines[1 + i].split())) for i in range(m)), key=lambda e: e[2])
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    total = 0
    for u, v, w in edges:
        a, b = find(u), find(v)
        if a != b:
            parent[a] = b; total += w
    return str(total)


print(mst(sys.stdin.read().rstrip("\n")))
